			if (!@ copy($src, $dest))
			{
				JLog::add(JText::_('JLIB_FILESYSTEM_ERROR_COPY_FAILED'), JLog::WARNING, 'jerror');
				return false;
			}
			$ret = true;
		}

		return $ret;
	}
}

